const restartButton = /** @type {HTMLButtonElement} */ (element("restart"));
const rewardDialog = /** @type {HTMLDialogElement} */ (
  element("reward-dialog")
);
const rewardImage = /** @type {HTMLImageElement} */ (element("reward-image"));
